(()=>{const e="theme-preference",o=document.documentElement,t=document.querySelector("#theme-preference");if(!t)return;let n="system";try{const t=localStorage.getItem(e);(t==="light"||t==="dark"||t==="system")&&(n=t)}catch{}const s=n=>{o.dataset.theme=n,t.value=n,window.dispatchEvent(new CustomEvent("themechange",{detail:n}));try{n==="system"?localStorage.removeItem(e):localStorage.setItem(e,n)}catch{}};s(n),t.addEventListener("change",e=>s(e.target.value))})()